const $=s=>document.querySelector(s),canvas=$('#cover');let images=[],selected=1,drag=null;
const initial=()=>({layout:'fracture',grade:'sunset',tagline:'GOOD PEOPLE. BAD DECISIONS.',ink:true,grain:true,intensity:65,assignments:[-1,0,-2,-3,1],crops:Array.from({length:5},()=>({x:0,y:0,zoom:1}))});let state=initial();
function loadImage(url){return new Promise((resolve,reject)=>{let im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('That image could not be opened. Try JPG, PNG, or WebP.'));im.src=url})}
function redraw(){state.tagline=$('#tagline').value;drawCover(canvas,images,$('#caption').value,state);$('#counter').textContent=`${$('#caption').value.length} / 40`;$('#scene-name').textContent=state.grade.toUpperCase()+' EDITION'}
function thumbs(){let box=$('#photos');box.replaceChildren();images.forEach((im,i)=>{let b=document.createElement('button');b.className='photo-thumb';b.title=`Use photo ${i+1} in selected panel`;b.setAttribute('aria-label',b.title);let img=document.createElement('img');img.src=im.src;img.alt=`Photo ${i+1}`;b.append(img);b.onclick=()=>{state.assignments[selected]=i;state.crops[selected]={x:0,y:0,zoom:1};syncCrop();redraw();$('#status').textContent=`Photo ${i+1} placed in panel ${selected+1}.`};box.append(b)});$('#photo-count').textContent=images.length+' photos loaded';let menu=$('#panel-content');menu.querySelectorAll('[data-photo-option]').forEach(o=>o.remove());images.forEach((im,i)=>{let option=document.createElement('option');option.value=String(i);option.textContent=`Your photo ${i+1}`;option.dataset.photoOption='';menu.append(option)});syncCrop()}
function syncCrop(){document.querySelectorAll('[data-panel]').forEach(b=>{let active=+b.dataset.panel===selected;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});$('#panel-content').value=String(state.assignments[selected]);$('#fill-all').disabled=state.assignments[selected]<0;for(let selector of ['#zoom','#pan-x','#pan-y','#recenter'])$(selector).disabled=state.assignments[selected]<0;document.querySelectorAll('.photo-thumb').forEach((b,i)=>b.classList.toggle('active',state.assignments[selected]===i));for(let axis of ['x','y']){$('#pan-'+axis).value=state.crops[selected][axis];$('#pan-'+axis+'-value').textContent=Math.round(state.crops[selected][axis]*100)+'%'}$('#zoom').value=state.crops[selected].zoom;$('#zoom-value').textContent=Math.round(state.crops[selected].zoom*100)+'%';$('#panel-name').textContent=String(selected+1).padStart(2,'0')}
async function upload(files){let valid=[...files].filter(f=>f.type.startsWith('image/'));if(!valid.length){$('#status').textContent='Choose an image file (JPG, PNG, or WebP).';return}let added=0;for(let file of valid.slice(0,12)){if(file.size>30*1024*1024){$('#status').textContent='Please use photos smaller than 30 MB.';continue}let url=URL.createObjectURL(file);try{let im=await loadImage(url);images.push(im);let panel=added===0?selected:(selected+added)%5;state.assignments[panel]=images.length-1;state.crops[panel]={x:0,y:0,zoom:1};added++}catch(e){URL.revokeObjectURL(url);$('#status').textContent=e.message}}thumbs();syncCrop();redraw();if(added)$('#status').textContent=`${added} photo${added>1?'s':''} added. Select a panel, then a photo to swap its cast.`;$('#photo').value=''}
$('#panel-picker').onclick=e=>{let b=e.target.closest('[data-panel]');if(!b)return;selected=+b.dataset.panel;syncCrop();$('#status').textContent=`Panel ${selected+1} selected. Choose its photo or original art below.`};
